ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  value: (payload.value filter (msg) ->
      sizeOf(
        (msg.toRecipients default [])
          filter (r) -> lower(r.emailAddress.address default "") == lower("Salesforce@devonshire-underwriting.co.uk")
      ) > 0
  ) map (msg) -> {
    id:      msg.id,
    subject: msg.subject,
    isRead:  msg.isRead
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output multipart/form-data
---
{
  parts: {
    file: {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": 'form-data; name="file"; filename="' ++ vars.pdfName ++ '.pdf"'
      },
      content: payload
    }
  }
}

