fun mapIndustry(payload: Object) = do { var corpus = lower( (vars.outputIDP.prompt.value.project.documentType default "") ++ " " ++ (vars.outputIDP.prompt.value.project.doctype default "") ++ " " ++ (vars.outputIDP.prompt.value.project.projectName default "") ++ " " ++ (vars.outputIDP.prompt.value.insured.namedInsured default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.typeOfTaxRisk default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.riskDescription default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent default "") ++ " " ++ (vars.outputIDP.prompt.value.policyTerms.coverScope default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.taxCounselOpinion default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++ (vars.outputIDP.prompt.value.keyRiskMitigants default "") )
// Use an Array of Objects instead of Object keys // avoids null score when industry name has spaces or special chars var industryKeywords = [ { industry: "Agriculture", keywords: ["farm", "agriculture", "crop", "livestock"] }, { industry: "Apparel", keywords: ["apparel", "fashion", "clothing", "garment"] }, { industry: "Banking", keywords: ["bank", "lending", "credit", "deposit", "mortgage"] }, { industry: "Biotechnology", keywords: ["biotech", "genomic", "pharma", "clinical"] }, { industry: "Chemicals", keywords: ["chemical", "polymer", "solvent", "petrochemical"] }, { industry: "Communications", keywords: ["communication", "broadcast", "publishing"] }, { industry: "Construction", keywords: ["construction", "building", "infrastructure", "contractor"] }, { industry: "Consulting", keywords: ["consulting", "advisory", "counsel", "linklaters", "marsh"] }, { industry: "Education", keywords: ["education", "school", "university", "training"] }, { industry: "Electronics", keywords: ["electronics", "semiconductor", "hardware"] }, { industry: "Energy", keywords: ["energy", "oil", "gas", "renewable", "power"] }, { industry: "Engineering", keywords: ["engineering", "mechanical", "civil", "structural"] }, { industry: "Entertainment", keywords: ["entertainment", "gaming", "film", "music"] }, { industry: "Environmental", keywords: ["environment", "sustainability", "carbon"] }, { industry: "Finance", keywords: ["finance", "investment", "tax", "withholding", "dividend", "interest", "fund", "asset", "holding", "equity", "capital", "liability", "audit", "fiscal", "nrit", "intragroup", "luxembourg", "sarl"] }, { industry: "Food & Beverage", keywords: ["food", "beverage", "restaurant", "catering"] }, { industry: "Government", keywords: ["government", "public sector", "ministry", "municipal"] }, { industry: "Healthcare", keywords: ["healthcare", "hospital", "medical", "clinic"] }, { industry: "Hospitality", keywords: ["hotel", "hospitality", "tourism", "resort"] }, { industry: "Insurance", keywords: ["underwriter", "premium", "reinsurance", "indemnity", "policy limit"] }, { industry: "Machinery", keywords: ["machinery", "equipment", "industrial"] }, { industry: "Manufacturing", keywords: ["manufacturing", "factory", "production", "assembly"] }, { industry: "Media", keywords: ["media", "content", "streaming"] }, { industry: "Not For Profit", keywords: ["nonprofit", "charity", "foundation", "ngo"] }, { industry: "Recreation", keywords: ["recreation", "sport", "leisure", "fitness"] }, { industry: "Retail", keywords: ["retail", "ecommerce", "store", "consumer"] }, { industry: "Shipping", keywords: ["shipping", "freight", "logistics", "cargo"] }, { industry: "Technology", keywords: ["technology", "software", "saas", "cloud", "platform"] }, { industry: "Telecommunications", keywords: ["telecom", "mobile", "network", "5g", "fiber"] }, { industry: "Transportation", keywords: ["transport", "airline", "rail", "fleet"] }, { industry: "Utilities", keywords: ["utility", "electric", "water", "waste"] }, { industry: "Other", keywords: [] },
]
var scored = industryKeywords map (entry) -> { industry: entry.industry, score: sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw)) }
var ranked = scored orderBy (- $.score) --- if (ranked[0].score > 0) ranked[0].industry else "Finance" }
--- { industry: mapIndustry(vars.outputIDP) }

