fun mapOwnership(payload: Object) =
  do {
    var corpus = lower(
      (vars.outputIDP.prompt.value.project.documentType          default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.doctype               default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.projectName           default "") ++ " " ++
      (vars.outputIDP.prompt.value.insured.namedInsured          default "") ++ " " ++
      (vars.outputIDP.prompt.value.insured.ultimateBeneficialOwner default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent       default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope        default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var ownershipKeywords = [
      {
        ownership: "Public",
        keywords: [
          "publicly listed", "publicly traded", "stock exchange",
          "listed company", "ipo", "shares listed", "stock market",
          "sec filing", "annual report", "public company"
        ]
      },
      {
        ownership: "Private",
        keywords: [
          "private equity", "privately held", "private company",
          "private ownership", "private investor", "pe fund",
          "venture capital", "privately owned", "private fund"
        ]
      },
      {
        ownership: "Subsidiary",
        keywords: [
          "subsidiary", "parent company", "holding company",
          "wholly owned", "group company", "sarl", "holdco",
          "subgroup", "controlled by", "owned by", "intragroup",
          "parent", "group structure", "co-investment"
        ]
      },
      {
        ownership: "Other",
        keywords: []
      }
    ]
    var scored = ownershipKeywords map (entry) -> {
