output application/json

fun mapNbiDeadline(outputIDP: Object) =
  do {
    var raw = vars.outputIDP.prompt.value.project.nbiDeadline default ""

    // scan returns Array of Arrays: [[fullMatch, g1, g2, g3], ...]
    // each inner array: [0]=full, [1]=day, [2]=month, [3]=year|null
    var parts = raw scan /(\d+)(?:st|nd|rd|th)\s+([A-Za-z]+)(?:\s+(\d{4}))?/

    var matched   = sizeOf(parts) > 0
    var dayStr    = if (matched) parts[0][1] default "" else ""
    var monthStr  = upper(if (matched) parts[0][2] default "" else "")

    // year from nbiDeadline if present, else fall back to dateOfSubmission
    var yearParts = (vars.outputIDP.prompt.value.project.dateOfSubmission default "January 2026")
      scan /(\d{4})/
    var yearStr = if (matched and parts[0][3] != null)
      parts[0][3]
    else
      if (sizeOf(yearParts) > 0) yearParts[0][1] default "2026" else "2026"

    var monthMap = {
      JANUARY:   "01", FEBRUARY:  "02", MARCH:     "03",
      APRIL:     "04", MAY:       "05", JUNE:      "06",
      JULY:      "07", AUGUST:    "08", SEPTEMBER: "09",
      OCTOBER:   "10", NOVEMBER:  "11", DECEMBER:  "12"
    }

    var monthNum  = monthMap[monthStr] default "01"
    var dayPadded = if (sizeOf(dayStr) == 1) "0" ++ dayStr else dayStr

    // date string YYYY-MM-DD reused for both outputs
    var dateStr   = yearStr ++ "-" ++ monthNum ++ "-" ++ dayPadded

    // Salesforce DateTime format: YYYY-MM-DDTHH:mm:ss.000+0000
    var dateTimeStr = dateStr ++ "T23:59:59.000+0000"
    ---
    if (raw == "" or !matched)
      { nbiDeadline: null, nbiDeadlineDatetime: null }
    else
      { nbiDeadline: dateStr, nbiDeadlineDatetime: dateTimeStr }
  }

---
{
  nbiDeadline:         mapNbiDeadline(vars.outputIDP).nbiDeadline,
  nbiDeadlineDatetime: mapNbiDeadline(vars.outputIDP).nbiDeadlineDatetime
}

%dw 2.0
output application/json

fun mapExpectedRevenue(outputIDP: Object) =
  do {
    var raw = vars.outputIDP.prompt.value.taxRisk.taxExposureEstimate default ""

    // scan for the first sequence of digits (ignoring decimals, commas, text)
    var parts = (raw as String) scan /(\d+)/
    ---
    if (sizeOf(parts) > 0)
      parts[0][1] as Number
    else
      null
  }

---
{
  ExpectedRevenue: mapExpectedRevenue(vars.outputIDP)
}

%dw 2.0
output application/json

fun mapLossReason(outputIDP: Object) =
  do {
    var corpus = lower(
      (vars.outputIDP.prompt.value.project.documentType          default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.doctype               default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.broker                default "") ++ " " ++
      (vars.outputIDP.prompt.value.insured.namedInsured          default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.jurisdiction          default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.requestedLimits   default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope        default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var lossReasonKeywords = [
      {
        lossReason: "No Activity / Broker Response",
        keywords: [
          "no response", "no activity", "unresponsive", "no reply",
          "broker silent", "no follow up", "not responded",
          "no feedback", "gone quiet", "no contact"
        ]
      },
      {
        lossReason: "Pricing",
        keywords: [
          "pricing", "too expensive", "premium too high",
          "cost too high", "rate too high", "unaffordable",
          "price sensitive", "cheaper alternative", "budget constraint"
        ]
      },
      {
        lossReason: "Coverage",
        keywords: [
          "coverage", "scope too narrow", "exclusion",
          "not covered", "coverage gap", "policy wording",
          "terms too restrictive", "insufficient cover"
        ]
      },
      {
        lossReason: "Existing Relationship",
        keywords: [
          "existing relationship", "incumbent", "existing insurer",
          "preferred insurer", "long standing", "already placed",
          "existing policy", "renewing with", "loyalty"
        ]
      },
      {
        lossReason: "Aggregation",
        keywords: [
          "aggregation", "accumulation", "portfolio limit",
          "aggregate exposure", "too much exposure",
          "concentration risk", "aggregate cap"
        ]
      },
      {
        lossReason: "Deal did not progress",
        keywords: [
          "did not progress", "not progressed", "deal fell through",
          "transaction aborted", "deal collapsed", "deal cancelled",
          "no longer proceeding", "abandoned", "deal dead"
        ]
      },
      {
        lossReason: "Declined - EV",
        keywords: [
          "declined ev", "enterprise value", "ev too low",
          "valuation concern", "ebitda", "ev declined"
        ]
      },
      {
        lossReason: "Declined - Sector",
        keywords: [
          "declined sector", "sector excluded", "sector appetite",
          "no appetite sector", "sector blacklist",
          "sector restriction", "industry excluded"
        ]
      },
      {
        lossReason: "Declined - Jurisdiction",
        keywords: [
          "declined jurisdiction", "jurisdiction excluded",
          "no appetite jurisdiction", "country restriction",
          "sanctioned", "jurisdiction risk", "territory excluded"
        ]
      },
      {
        lossReason: "Declined - Capacity",
        keywords: [
          "declined capacity", "no capacity", "capacity exhausted",
          "insufficient capacity", "limit unavailable",
          "capacity constraint", "no line available"
        ]
      },
      {
        lossReason: "Declined - Broker Relationship",
        keywords: [
          "declined broker", "broker relationship", "broker not approved",
          "no broker agreement", "broker panel",
          "broker not on panel", "unrecognised broker"
        ]
      },
      {
        lossReason: "Other",
        keywords: []
      }
    ]
    var scored = lossReasonKeywords map (entry) -> {
      lossReason: entry.lossReason,
      score: sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw))
    }
    var ranked = scored orderBy (- $.score)
    ---
    if (ranked[0].score > 0) ranked[0].lossReason
    else "No Activity / Broker Response"
  }

---
{
  lossReason: mapLossReason(vars.outputIDP)
}

