fun mapStageFields(outputIDP: Object) = do { var corpus = lower( (payload.prompt.value.project.documentType default "") ++ " " ++ (payload.prompt.value.project.doctype default "") ++ " " ++ (payload.prompt.value.project.nbiDeadline default "") ++ " " ++ (payload.prompt.value.taxRisk.riskDescription default "") ++ " " ++ (payload.prompt.value.taxRisk.riskRating default "") ++ " " ++ (payload.prompt.value.taxRisk.insuredTaxEvent default "") ++ " " ++ (payload.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++ (payload.prompt.value.taxRisk.taxCounselOpinion default "") ++ " " ++ (payload.prompt.value.policyTerms.requestedLimits default "") ++ " " ++ (payload.prompt.value.policyTerms.coverScope default "") ++ " " ++ (payload.prompt.value.keyRiskMitigants default "") ) var stageBands = [ { stageName: "Submission received", probability: 10.0, forecastCategory: "Pipeline", keywords: [ "submission", "submitted", "nbi", "new business intake", "received", "documents provided", "tbc", "to be confirmed", "under consideration" ] }, { stageName: "Quoted", probability: 35.0, forecastCategory: "Pipeline", keywords: [ "quoted", "quote issued", "indicative terms", "indicative quote", "terms issued", "nbi deadline", "offer issued", "indication provided", "pricing provided" ] }, { stageName: "In Underwriting", probability: 75.0, forecastCategory: "Best Case", keywords: [ "underwriting", "under review", "due diligence", "legal opinion", "tax audit", "audit initiated", "provisional", "assessment", "objection", "not yet final", "allegation", "linklaters", "tax counsel", "diligence" ] }, { stageName: "Bound (Conditional)", probability: 90.0, forecastCategory: "Commit", keywords: [ "bound", "conditional", "mandate", "mandated", "terms agreed", "premium agreed", "binding", "placed", "order given", "ntp", "notice to proceed", "conditional bind" ] }, { stageName: "Closed Won", probability: 100.0, forecastCategory: "Closed", keywords: [ "closed won", "policy issued", "cover incepted", "policy in force", "premium paid", "finalised", "finalized", "completed successfully" ] }, { stageName: "Closed Lost", probability: 0.0, forecastCategory: "Omitted", keywords: [ "closed lost", "declined", "rejected", "no appetite", "withdrawn", "cancelled", "not proceeding", "ruled out", "deal dead", "abandoned", "lost" ] } ] var scored = stageBands map (entry) -> { stageName: entry.stageName, probability: entry.probability, forecastCategory: entry.forecastCategory, score: sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw)) } var ranked = scored orderBy (- $.score) var best = if (ranked[0].score > 0) ranked[0] else { stageName: "Quoted", probability: 35.0, forecastCategory: "Pipeline", score: 0 } --- { stageName: best.stageName, probability: best.probability, forecastCategory: best.forecastCategory } }
--- { stageName: mapStageFields(payload).stageName, probability: mapStageFields(payload).probability, forecastCategory: mapStageFields(payload).forecastCategory }

