fun mapProductType(outputIDP: Object) =
  do {
    var corpus = lower(
      (vars.outputIDP.prompt.value.project.documentType          default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.doctype               default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.typeOfTaxRisk         default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent       default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.policyType        default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope        default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var productTypeKeywords = [
      {
        productType: "Contingent",
        keywords: [
          "contingent", "contingency", "specific contingency",
          "contingent liability", "known risk", "identified risk",
          "contingent risk", "litigation", "dispute"
        ]
      },
      {
        productType: "Tax",
        keywords: [
          "tax", "taxation", "withholding", "nrit",
          "tax liability", "tax risk", "tax audit",
          "tax submission", "tax insurance", "fiscal",
          "dividend", "interest payment", "intragroup",
          "tax authority", "tax assessment", "tax exposure"
        ]
      },
      {
        productType: "W&I",
        keywords: [
          "warranty", "indemnity", "w&i", "warranties and indemnities",
          "representation", "warranty and indemnity",
          "acquisition", "m&a", "merger", "sale and purchase",
          "spa", "share purchase", "rep and warranty"
        ]
      }
    ]
    var scored = productTypeKeywords map (entry) -> {
      productType: entry.productType,
      score: sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw))
    }
    var ranked = scored orderBy (- $.score)
    ---
    if (ranked[0].score > 0) ranked[0].productType
    else "W&I"
  }

---
{
  productType: mapProductType(vars.outputIDP)
}

