fun mapProductSubType(outputIDP: Object) =
  do {
    var corpus = lower(
      (vars.outputIDP.prompt.value.project.documentType          default "") ++ " " ++
      (vars.outputIDP.prompt.value.project.doctype               default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.typeOfTaxRisk         default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.policyType        default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope        default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var subTypeKeywords = [
      {
        subType: "Adverse Judgement",
        keywords: [
          "adverse judgement", "adverse judgment", "adverse outcome",
          "tax assessment", "tax audit", "audit outcome",
          "assessment notified", "provisional assessment",
          "penalty", "withholding tax", "nrit",
          "tax liability", "tax exposure", "tax cuota"
        ]
      },
      {
        subType: "Title",
        keywords: [
          "title", "title insurance", "title defect",
          "ownership", "land registry", "title risk",
          "property title", "encumbrance", "lien"
        ]
      },
      {
        subType: "Capital Protection",
        keywords: [
          "capital protection", "capital preservation",
          "downside protection", "capital guarantee",
          "principal protection", "protected investment"
        ]
      },
      {
        subType: "Judgement Preservation",
        keywords: [
          "judgement preservation", "judgment preservation",
          "preserve judgement", "protect award",
          "appeal risk", "appeal insurance",
          "reversal risk", "existing award"
        ]
      },
      {
        subType: "Enforcement",
        keywords: [
          "enforcement", "enforce", "enforceable",
          "collection risk", "recovery", "debt recovery",
          "award enforcement", "judgment enforcement",
          "cross-border enforcement"
        ]
      },
      {
        subType: "ATE",
        keywords: [
          "ate", "after the event", "litigation insurance",
          "legal costs", "adverse costs", "cost insurance",
          "litigation funding", "legal expenses"
        ]
      }
    ]
    var scored = subTypeKeywords map (entry) -> {
      subType: entry.subType,
      score:   sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw))
    }
    var ranked = scored orderBy (- $.score)
    ---
    if (ranked[0].score > 0) ranked[0].subType
    else "Adverse Judgement"
  }

---
{
  productSubType: mapProductSubType(vars.outputIDP)
}

