output application/json

fun mapClaimStatus(outputIDP: Object) =
  do {
    var corpus = lower(
      (vars.outputIDP.prompt.value.project.documentType          default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.typeOfTaxRisk         default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.insuredTaxEvent       default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.priorAuditOrClearance default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope        default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var claimStatusKeywords = [
      {
        claimStatus: "No Threat",
        keywords:    []
      },
      {
        claimStatus: "Threat",
        keywords: [
          "threat", "threatened", "potential claim",
          "risk of audit", "risk of challenge", "possible dispute",
          "under scrutiny", "at risk", "exposure identified"
        ]
      },
      {
        claimStatus: "Pre-Action",
        keywords: [
          "pre-action", "pre action", "audit initiated",
          "audit commenced", "tax audit", "investigation opened",
          "inquiry opened", "notice issued", "formal notice",
          "letter of concern", "information request"
        ]
      },
      {
        claimStatus: "First Instance",
        keywords: [
          "first instance", "provisional assessment",
          "assessment notified", "tax assessment",
          "objection filed", "allegation", "not yet final",
          "contested", "challenge filed", "response submitted"
        ]
      },
      {
        claimStatus: "Appeal",
        keywords: [
          "appeal", "appealed", "appellate",
          "under appeal", "appeal pending", "supreme court",
          "higher court", "court of appeal", "cjeu",
          "european court", "judicial review"
        ]
      },
      {
        claimStatus: "Portfolio",
        keywords: [
          "portfolio", "multiple claims", "series of claims",
          "batch", "group of risks", "portfolio risk",
          "multiple years", "series of transactions"
        ]
      },
      {
        claimStatus: "Final Verdict / Settled",
        keywords: [
          "final verdict", "settled", "settlement",
          "final judgement", "final judgment", "resolved",
          "concluded", "closed", "agreed settlement",
          "final decision", "binding decision"
        ]
      }
    ]
    var scored = claimStatusKeywords map (entry) -> {
      claimStatus: entry.claimStatus,
      score:       sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw))
    }
    var ranked = scored orderBy (- $.score)
    ---
    if (ranked[0].score > 0) ranked[0].claimStatus
    else "No Threat"
  }

---
