      (vars.outputIDP.prompt.value.policyTerms.requestedLimits   default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.retention         default "") ++ " " ++
      (vars.outputIDP.prompt.value.keyRiskMitigants              default "")
    )
    var riskLayerKeywords = [
      {
        riskLayer: "Primary",
        keywords: [
          "primary", "primary layer", "first loss",
          "ground up", "primary cover", "primary policy",
          "first line", "primary insurer"
        ]
      },
      {
        riskLayer: "Excess",
        keywords: [
          "excess", "excess layer", "excess of loss",
          "xol", "top up", "top-up", "second layer",
          "excess cover", "above primary", "umbrella",
          "additional layer", "layered"
        ]
      }
    ]
    var scored = riskLayerKeywords map (entry) -> {
      riskLayer: entry.riskLayer,
      score:     sizeOf(entry.keywords filter (kw) -> corpus contains lower(kw))
    }
    var ranked = scored orderBy (- $.score)
    ---
    if (ranked[0].score > 0) ranked[0].riskLayer
    else "Primary"
  }

---
{
  riskLayer: mapRiskLayer(vars.outputIDP)
