fun mapPremiumTaxRate(outputIDP: Object) =
  do {

    var corpus =
      (vars.outputIDP.prompt.value.policyTerms.premiumTaxRate     default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.taxRate            default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.ipt                default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope         default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.riskDescription        default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.taxExposureEstimate     default "")


    var explicitRate =
      corpus scan /(?:ipt|tax rate|premium tax|rate)[^\d]*(\d{1,3})(?:\s*%)?/


    var percentRate =
      corpus scan /(\d{1,3})\s*%/
    ---
    if (sizeOf(explicitRate) > 0)
      explicitRate[0][1] as Number
    else if (sizeOf(percentRate) > 0)
      percentRate[0][1] as Number
    else
      0
  }

---
{
  premiumTaxRate: mapPremiumTaxRate(vars.outputIDP)
}

