fun mapPremiumTaxRate(outputIDP: Object) =
  do {
    var corpus =

      // W&I object fields
      (vars.outputIDP.prompt.value.pricing.premium                     default "") ++ " " ++
      (vars.outputIDP.prompt.value.pricing.rateOnLine                  default "") ++ " " ++
      (vars.outputIDP.prompt.value.pricing.pricingTables               default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyRequirements.policyType       default "") ++ " " ++
      (vars.outputIDP.prompt.value.additionalInformation.otherNotes    default "")

    // Step 1 — explicit label match: "ipt 12", "tax rate 8%", "rate: 19", "rol 1.5%"
    var explicitRate =
      corpus scan /(?:ipt|tax rate|premium tax|rate on line|rol|rate)[^\d]*(\d{1,3})(?:\s*%)?/

    // Step 2 — fallback: any standalone percentage e.g. "8%", "12 %"
    var percentRate =
      corpus scan /(\d{1,3})\s*%/
    ---
    if (sizeOf(explicitRate) > 0)
      explicitRate[0][1] as Number
    else if (sizeOf(percentRate) > 0)
      percentRate[0][1] as Number
    else
      0
  }

---
{
  premiumTaxRate: mapPremiumTaxRate(vars.outputIDP)
}

%dw 2.0
output application/json

fun mapAmount(outputIDP: Object) =
  do {
    // Priority fields — both old (taxRisk) and new (policyRequirements/valuation) objects
    var primary =
      (vars.outputIDP.prompt.value.policyRequirements.policyLimitOptions      default "") ++ " " ++
      (vars.outputIDP.prompt.value.additionalInformation.otherNotes            default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.requestedLimits                default "") ++ " " ++
      (vars.outputIDP.prompt.value.taxRisk.taxExposureEstimate                 default "")

    // Fallback fields — valuation, retention, cover scope
    var fallback =
      (vars.outputIDP.prompt.value.valuation.transactionValue                  default "") ++ " " ++
      (vars.outputIDP.prompt.value.valuation.enterpriseValue                   default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyRequirements.policyRetentionOptions   default "") ++ " " ++
      (vars.outputIDP.prompt.value.policyTerms.coverScope                      default "")

    // Step 1 — explicit limit label + number
    // matches: "limit: 10,000,000", "policy limit GBP 5000000", "sum insured 10000000"
    var labelledMatch = primary scan /(?:limit|policy limit|cover limit|sum insured)[^\d]*(\d[\d,]*)/

    // Step 2 — large plain numbers (≥ 5 digits) in primary fields
    var plainMatch = primary scan /(\d[\d,]{4,})/

    // Step 3 — fallback: large number in secondary fields
    var fallbackMatch = fallback scan /(\d[\d,]{4,})/
    ---
    if (sizeOf(labelledMatch) > 0)
      (labelledMatch[0][1] replace "," with "") as Number + 0.0
    else if (sizeOf(plainMatch) > 0)
      (plainMatch[0][1] replace "," with "") as Number + 0.0
    else if (sizeOf(fallbackMatch) > 0)
      (fallbackMatch[0][1] replace "," with "") as Number + 0.0
    else
      null
  }

---
{
  amount: mapAmount(vars.outputIDP)
}

