ce", keywords: ["underwriter", "premium", "reinsurance", "indemnity", "policy limit"] }, { industry: "Machinery", keywords: ["machinery", "equipment", "industrial"] }, { industry: "Manufacturing", keywords: ["manufacturing", "factory", "production", "assembly"] }, { industry: "Media", keywords: ["media", "content", "streaming"] }, { industry: "Not For Profit", keywords: ["nonprofit", "charity", "foundation", "ngo"] }, { industry: "Recreation", keywords: ["recreation", "sport", "leisure", "fitness"] }, { industry: "Retail", keywords: ["retail", "ecommerce", "store", "consumer"] }, { industry: "Shipping", keywords: ["shipping", "freight", "logistics", "cargo"] }, { industry: "Technology", keywords: ["technology", "software", "saas", "cloud", "platform"] }, { industry: "Telecommunications", keywords: ["telecom", "mobile", "network", "5g", "fiber"] }, { industry: "Transportation", keywords: ["transport", "airline", "rail", "fleet"] }, { industry: "Utilities", keywords: ["utility", "electric", "water", "waste"] }, { industry: "Other", keywords: [] },
