fun mapBudgetConfirmed(outputIDP: Object) = do { var corpus = lower( (vars.outputIDP.prompt.value.project.documentType default "") ++ " " ++ (vars.outputIDP.prompt.value.project.doctype default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.taxExposureEstimate default "") ++ " " ++ (vars.outputIDP.prompt.value.taxRisk.riskDescription default "") ++ " " ++ (vars.outputIDP.prompt.value.policyTerms.requestedLimits default "") ++ " " ++ (vars.outputIDP.prompt.value.policyTerms.retention default "") ++ " " ++ (vars.outputIDP.prompt.value.policyTerms.coverScope default "") ++ " " ++ (vars.outputIDP.prompt.value.keyRiskMitigants default "") ) var confirmedKeywords = [ "budget confirmed", "budget approved", "budget agreed", "budget allocated", "premium confirmed", "premium agreed", "limit confirmed", "limit agreed", "limit approved", "approved budget", "confirmed budget", "funds confirmed", "funds approved", "financing confirmed", "confirmed limit", "agreed limit", "cost approved", "cost confirmed" ] --- sizeOf(confirmedKeywords filter (kw) -> corpus contains lower(kw)) > 0 }
--- { budgetConfirmed: mapBudgetConfirmed(vars.outputIDP) }

