output application/json

fun mapNbiDeadline(outputIDP: Object) =
  do {
    var raw = vars.outputIDP.prompt.value.project.nbiDeadline default ""

    // scan returns Array of Arrays: [[fullMatch, g1, g2, g3], ...]
    // each inner array: [0]=full, [1]=day, [2]=month, [3]=year|null
    var parts = raw scan /(\d+)(?:st|nd|rd|th)\s+([A-Za-z]+)(?:\s+(\d{4}))?/

    var matched   = sizeOf(parts) > 0
    var dayStr    = if (matched) parts[0][1] default "" else ""
    var monthStr  = upper(if (matched) parts[0][2] default "" else "")

    // year from nbiDeadline if present, else fall back to dateOfSubmission
    var yearParts = (vars.outputIDP.prompt.value.project.dateOfSubmission default "January 2026")
      scan /(\d{4})/
    var yearStr = if (matched and parts[0][3] != null)
      parts[0][3]
    else
      if (sizeOf(yearParts) > 0) yearParts[0][1] default "2026" else "2026"

    var monthMap = {
      JANUARY:   "01", FEBRUARY:  "02", MARCH:     "03",
      APRIL:     "04", MAY:       "05", JUNE:      "06",
      JULY:      "07", AUGUST:    "08", SEPTEMBER: "09",
      OCTOBER:   "10", NOVEMBER:  "11", DECEMBER:  "12"
    }

    var monthNum  = monthMap[monthStr] default "01"
    var dayPadded = if (sizeOf(dayStr) == 1) "0" ++ dayStr else dayStr

    // date string YYYY-MM-DD reused for both outputs
    var dateStr   = yearStr ++ "-" ++ monthNum ++ "-" ++ dayPadded

    // Salesforce DateTime format: YYYY-MM-DDTHH:mm:ss.000+0000
    var dateTimeStr = dateStr ++ "T23:59:59.000+0000"
    ---
    if (raw == "" or !matched)
      { nbiDeadline: null, nbiDeadlineDatetime: null }
    else
      { nbiDeadline: dateStr, nbiDeadlineDatetime: dateTimeStr }
  }

---
{
  nbiDeadline:         mapNbiDeadline(vars.outputIDP).nbiDeadline,
  nbiDeadlineDatetime: mapNbiDeadline(vars.outputIDP).nbiDeadlineDatetime
}

