fun mapExpectedRevenue(outputIDP: Object) =
  do {
    var raw = vars.outputIDP.prompt.value.valuation.transactionValue default ""

    // scan for the first sequence of digits (ignoring decimals, commas, text)
    var parts = (raw as String) scan /(\d+)/
    ---
    if (sizeOf(parts) > 0)
      parts[0][1] as Number
    else
      null
  }

---
{
  ExpectedRevenue: mapExpectedRevenue(vars.outputIDP)
}

