ROI_Analysis_Completed__c: "false", StageName: vars.stage.stageName, Type: vars.productType.productType,
// Connexa custom fields Account_Number__c: vars.outputIDP.invoiceMetadata.policyNumber default vars.outputIDP.invoiceMetadata.invoiceNumber default "",
Business_Sector__c: vars.businesSector.businessSector,
