Insured_Jurisdiction__c: vars.InsuredJurisdiction.insuredJurisdiction, Key_Risk_Jurisdiction__c: vars.InsuredJurisdiction.insuredJurisdiction, Product_Sub_Type__c: vars.productSubType.productSubType, Claim_Status__c: vars.claimStatus.claimStatus, Governing_Law__c: vars.InsuredJurisdiction.insuredJurisdiction,
// NBI_Deadline__c → invoice due date (invoiceDate + paymentDueDays) NBI_Deadline__c: vars.closeDateformating.nbiDeadlineDatetime,
Risk_Layer__c: vars.riskLayer.riskLayer, Premium_Tax_Rate__c: vars.premiumTaxRate.premiumTaxRate, Broker_Commission__c: "20.0", Binder_Fee__c: "2.5", Devonshire_Commission__c: "10.0",
// Layer_Limit__c → total invoice amount Layer_Limit__c: vars.outputIDP.lineItemsSummary.totalInvoiceAmount default vars.ExpectedRevenue.ExpectedRevenue,
// Devonshire_Limt_of_Layer__c → premium tax amount Devonshire_Limt_of_Layer__c: vars.outputIDP.lineItemsSummary.premiumTaxAmount default vars.premiumTaxRate.premiumTaxRate }
